#!/usr/bin/env python3
"""Validate commitments.csv against the schema in README.md.

Usage: python scripts/validate.py [path/to/commitments.csv]
Exit code 0 if valid, 1 otherwise. Standard library only.
"""
import csv
import re
import sys
from datetime import date
from pathlib import Path

FIELDS = [
    "id", "developer", "commitment_text", "commitment_type", "source_url",
    "source_archive_url", "date_made", "stated_deadline", "status",
    "followup_text", "followup_url", "date_followup", "notes", "last_checked",
]
TYPES = {"threshold", "evaluation", "disclosure", "third_party_access",
         "security", "governance", "other"}
STATUSES = {"open", "reported_fulfilled", "revised", "withdrawn",
            "no_public_followup"}
ID_RE = re.compile(r"^[A-Z0-9]+-\d{4}-\d{3}$")
URL_RE = re.compile(r"^https?://")


def is_iso(s: str) -> bool:
    try:
        date.fromisoformat(s)
        return True
    except ValueError:
        return False


def main(path: Path) -> int:
    errors = []
    with path.open(newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != FIELDS:
            errors.append(f"header mismatch: {reader.fieldnames}")
            return report(errors)
        seen = set()
        for n, row in enumerate(reader, start=2):
            where = f"row {n} ({row.get('id') or '?'})"
            if not ID_RE.match(row["id"]):
                errors.append(f"{where}: bad id")
            if row["id"] in seen:
                errors.append(f"{where}: duplicate id")
            seen.add(row["id"])
            for req in ("developer", "commitment_text", "source_url"):
                if not row[req].strip():
                    errors.append(f"{where}: {req} is required")
            if row["commitment_type"] not in TYPES:
                errors.append(f"{where}: bad commitment_type")
            if row["status"] not in STATUSES:
                errors.append(f"{where}: bad status")
            if not URL_RE.match(row["source_url"]):
                errors.append(f"{where}: source_url not a URL")
            for d in ("date_made", "last_checked"):
                if not is_iso(row[d]):
                    errors.append(f"{where}: {d} not ISO date")
            if row["stated_deadline"] != "none" and not is_iso(row["stated_deadline"]):
                errors.append(f"{where}: stated_deadline must be ISO date or 'none'")
            if row["status"] in {"reported_fulfilled", "revised", "withdrawn"}:
                if not row["followup_url"] or not is_iso(row["date_followup"]):
                    errors.append(f"{where}: status {row['status']} needs followup_url and date_followup")
            if row["status"] == "no_public_followup" and row["stated_deadline"] == "none":
                errors.append(f"{where}: no_public_followup requires a stated_deadline")
    return report(errors)


def report(errors):
    if errors:
        print("\n".join(errors))
        print(f"{len(errors)} error(s)")
        return 1
    print("ok")
    return 0


if __name__ == "__main__":
    p = Path(sys.argv[1]) if len(sys.argv) > 1 else Path(__file__).resolve().parents[1] / "commitments.csv"
    sys.exit(main(p))
